 "t35_0": {
  "q": "队列研究（cohort study）的显著特点是？",
  "choices": {
   "从结局回顾暴露": "从结局状态选择对象再追溯暴露是病例对照思路。",
   "从暴露出发向前随访到结局，可计算RR": "队列研究从暴露状态出发向前随访，能明确时间顺序，计算RR/AR，因果论证力较强。",
   "只调查现况": "横断面描述现况，队列关注随访发生过程。",
   "不设对照组": "队列可设置未暴露或不同暴露对照。"
  }
 },
 "t35_1": {
  "q": "病例对照研究最适合用于？",
  "choices": {
   "常见病长期随访": "常见病可做队列，罕见病才尤其体现病例对照的效率优势。",
   "发病率很低的罕见病（回顾暴露史查病因线索）": "罕见病若做队列需极大人群，病例对照从已发生的病例出发回顾暴露，效率高代价小。",
   "验证因果": "观察性病例对照不能单凭设计确证因果。",
   "测量灵敏度": "诊断准确性研究需待评试验与参考标准，不能由一般病例对照设计代替。"
  }
 },
 "t35_2": {
  "q": "横断面研究最主要的局限是？",
  "choices": {
   "太贵": "横断面通常较便捷，费用不是其主要固有限制。",
   "暴露与疾病同时测量，难以判断因果先后": "横断面在同一时点测量暴露和疾病，'先有鸡还是先有蛋'难以厘清，只能提供关联线索。",
   "无法计算率": "可以估计患病率，但通常不能直接估计发病率。",
   "样本量大": "样本量大不是固有缺陷，关键是时间顺序不清。"
  }
 },
 "t35_3": {
  "q": "对'吸烟与肺癌'因果研究证据强度最大的设计是？",
  "choices": {
   "横断面": "同时测量常难确立吸烟先于肺癌。",
   "病例对照": "病例对照可提供证据，但暴露回顾与选择更易受偏倚影响。",
   "队列研究（或RCT，但伦理受限）": "队列研究时间顺序明确、可计算RR，证据等级高于横断面和病例对照。",
   "个案报道": "个案缺少可靠对照，因果证据有限。"
  }
 },
 "bank202609-t35-concept-1-1": {
  "q": "病例对照研究通常按什么选择入组？",
  "choices": {
   "结局状态": "典型病例对照设计先按病例和对照抽样再比较暴露。",
   "随机治疗分组": "按随机治疗分组是试验设计逻辑，不是病例对照抽样定义。",
   "未来暴露结果": "病例对照先按有无结局入组，不按未来暴露结果。",
   "P值大小": "P值是分析结果，不应作为入组依据。"
  }
 },
 "bank202609-t35-concept-2-1": {
  "q": "横断面研究最常见的时间解释限制？",
  "choices": {
   "暴露与结局先后不清": "同时测量使反向因果及时间顺序难判断。",
   "不能描述患病率": "横断面正可描述调查时点患病率。",
   "不能计算人数": "人数可直接统计，局限不在不能计数。",
   "所有关联必为因果": "先后不清和混杂使关联不能自动成为因果。"
  }
 },
 "bank202609-t35-concept-3-1": {
  "q": "队列研究中失访与预后相关，可能？",
  "choices": {
   "产生选择偏倚": "失访机制影响结局观察，需评估与敏感性分析。",
   "必然无偏": "若失访依赖预后，剩余样本可能不代表原队列。",
   "只降低字体清晰度": "这是研究有效性问题，与字体无关。",
   "自动校正混杂": "失访筛选不能自动控制混杂。"
  }
 },
 "bank202609-t35-concept-4-1": {
  "q": "生态学关联直接用于个体解释，风险？",
  "choices": {
   "生态学谬误": "群体层面关系不能自动推出个体层面关系。",
   "提高个体因果证据": "群体层面关联不保证个体层面同方向关系。",
   "等同个体随机试验": "生态数据没有个体随机分配产生的可比性。",
   "消除混杂": "群体与个体层面均可能存在混杂。"
  }
 },
