 "t36_0": {
  "q": "RCT中随机化的主要价值是？",
  "choices": {
   "节省时间": "随机化主要控制系统性分组差异，不以省时为目的。",
   "均衡已知和未知混杂因素（保证可比性）": "随机化使各组在已知和未知的混杂因素上达到均衡，是因果推断的基础。",
   "让医生更方便": "医生便利不等于避免选择性分配。",
   "提高灵敏度": "灵敏度是诊断性能，不是随机化直接目标。"
  }
 },
 "t36_1": {
  "q": "双盲试验中'不知分组情况'的双方是？",
  "choices": {
   "患者和家属": "仅家属不知情不能代表执行或评估研究者设盲。",
   "患者和执行/评价的医务研究者": "双盲=研究对象和研究者（执行治疗、评价结局者）均不知分组，防止预期偏倚。",
   "患者和药师": "药师是否设盲因流程不同而异，需明确具体角色，不能替代研究者描述。",
   "患者和保安": "保安并非影响干预执行与结局评价的主要研究角色。"
  }
 },
 "t36_2": {
  "q": "意向性分析（ITT）的含义是？",
  "choices": {
   "只分析完成试验者": "只分析完成者可能破坏原随机分组的可比性。",
   "按最初的随机分组分析所有对象（含脱失者）": "ITT坚持随机化原则，即使有人脱失、不依从也按原分组分析，避免破坏随机化带来的偏倚。",
   "只分析有效者": "只留有效者按结局选择样本，会夸大效果。",
   "剔除异常值": "删异常值不是ITT定义，任何排除都需预先依据与透明报告。"
  }
 },
 "t36_3": {
  "q": "交叉设计（crossover）相比平行设计的主要优点是？",
  "choices": {
   "样本更大": "自身对照常提高效率，不以扩大样本为优势。",
   "每个受试者先后接受两种干预，自身对照减少个体差异、效率高": "交叉设计让同一对象先后接受两种处理（中间有洗脱期），排除个体差异，所需样本更少。",
   "无需洗脱期": "交叉试验可能需要洗脱期以控制残留效应。",
   "只适用于生存数据": "不可逆事件通常不适合交叉，绝非只适用于生存资料。"
  }
 },
 "bank202609-t36-concept-1-1": {
  "q": "分配隐藏发生在哪个关键阶段？",
  "choices": {
   "入组及分配前防止预知分组": "分配隐藏防止研究者按下一组安排选择性入组。",
   "仅发表论文后": "发表后已无法阻止招募时选择性入组。",
   "仅统计绘图时": "绘图在分配之后，不能防止预知下一分组。",
   "仅数据备份时": "备份保护文件，不控制治疗分配信息。"
  }
 },
 "bank202609-t36-concept-2-1": {
  "q": "ITT分析通常按什么分组？",
  "choices": {
   "原随机分组": "ITT维护随机化比较，但缺失结局仍需适当处理。",
   "实际最后一次用药": "按实际用药属于不同分析策略，不能替代原分组ITT。",
   "只保留依从者": "依从者分析可能选择有特定预后的人。",
   "按疗效好坏重分": "按疗效重分会引入严重的结局驱动选择偏倚。"
  }
 },
 "bank202609-t36-concept-3-1": {
  "q": "开放标签试验仍可对谁实施盲法？",
  "choices": {
   "结局评估者或分析者": "不同角色的盲法可分别设计和报告。",
   "绝不可能任何盲法": "患者和治疗者知情不妨碍另设独立盲态评估者。",
   "只能期刊编辑": "编辑不知分组不是试验中控制结局评估偏倚的主要办法。",
   "只能患者家属": "家属盲态不能替代独立评估者或分析者盲态。"
  }
 },
 "bank202609-t36-concept-4-1": {
  "q": "集群随机试验按个人独立分析而忽略簇，风险？",
  "choices": {
   "低估标准误等错误": "随机化单位与分析相关结构需匹配。",
   "提高随机化效力": "分析忽略簇不会增强按簇随机化的设计效力。",
   "自动消除簇内相关": "簇内依赖由数据结构产生，忽略它不会消失。",
   "结论必不变": "标准误改变可能改变置信区间与显著性判断。"
  }
 },
