 "t14_0": {
  "q": "Logistic回归适用于结局变量为？",
  "choices": {
   "连续变量": "普通二项Logistic不是连续结局回归。",
   "二分类变量": "Logistic回归的结局是二分类变量（如患病/未患病），线性回归则要求结局连续。",
   "时间变量": "Logistic通常不利用事件时间与删失信息。",
   "任何变量": "不同结局类型需不同模型，不能不加区分通用。"
  }
 },
 "t14_1": {
  "q": "某Logistic回归结果显示吸烟的OR=2.3（95%CI: 1.5~3.5），解读为？",
  "choices": {
   "吸烟者患病的比值是不吸烟者的2.3倍，且区间不含1有统计学意义": "OR=2.3表示吸烟者发病的比值是不吸烟者的2.3倍；95%CI不含1说明有统计学意义。",
   "吸烟使患病风险降低": "OR>1表示模型中的事件优势更高，而不是降低。",
   "OR值无效": "给定估计与区间本身不能判定无效，仍需评估设计和模型。",
   "吸烟者患病率是2.3/100": "OR是两组优势的比，不是患病概率百分数。"
  }
 },
 "t14_2": {
  "q": "OR与RR的关系是？",
  "choices": {
   "两者完全相同": "优势与风险分母不同，只有某些条件下才近似。",
   "疾病罕见时OR≈RR，且OR常用于病例对照研究": "罕见病时OR近似RR；病例对照研究无法直接计算RR，常用OR作为关联指标。",
   "OR一定大于RR": "保护性关联时OR可小于RR，“一定大于”不成立。",
   "RR常用于病例对照研究": "常规病例对照按结局抽样，通常不能直接估计人群风险及RR。"
  }
 },
 "t14_3": {
  "q": "Logistic回归相比单因素分析（如简单卡方）的最大优势是？",
  "choices": {
   "计算更快": "主要价值是建模与调整，不是保证计算更快。",
   "可以同时控制多个混杂因素": "多因素Logistic回归可同时调整多个混杂因素，得出'校正后'的独立关联，比单因素分析更可靠。",
   "不需要样本量": "多变量模型仍需足够样本和事件信息。",
   "结果总是显著": "调整后结果可能显著也可能不显著。"
  }
 },
 "bank202609-t14-concept-1-1": {
  "q": "结局很常见时把OR解释为RR，可能怎样？",
  "choices": {
   "明显夸大或歪曲相对风险解释": "OR和RR定义不同，罕见结局时近似才较合理。",
   "必然完全相等": "结局常见时优势和风险差距更大，二者不必相等。",
   "OR必小于RR": "OR与RR大小还取决于关联方向，不能统一说OR更小。",
   "不会影响任何结论": "把优势当风险会改变效应解读，可能影响结论。"
  }
 },
 "bank202609-t14-concept-2-1": {
  "q": "预测变量完全区分有无事件，Logistic可能出现？",
  "choices": {
   "完全分离，常规估计发散": "完全分离时可考虑惩罚或其他适当估计方法。",
   "保证模型可推广": "完美区分可能只是样本偶然现象，不能保证推广。",
   "标准误必为0": "分离可能导致系数及标准误异常大，不是为0。",
   "模型不需验证": "训练中的完全区分尤其需要独立验证与适当估计。"
  }
 },
 "bank202609-t14-concept-3-1": {
  "q": "Logistic系数指数化后通常是什么？",
  "choices": {
   "相应单位变化的OR": "logit链接将线性预测子与优势对数联系。",
   "RR必然值": "exp(β)给出优势比，不直接给出风险比。",
   "风险差": "风险差是概率之差，不是logit系数的指数。",
   "生存概率": "生存概率需要时间信息和生存模型。"
  }
 },
 "bank202609-t14-concept-4-1": {
  "q": "连续变量与logit关系不线性时，可以考虑？",
  "choices": {
   "样条等合适函数形式": "非线性建模应结合目标、样本量和预设策略。",
   "只删除所有大值": "随意删除大值改变样本人群，不能合理修复函数形式。",
   "继续宣称线性已满足": "已有非线性证据时不能继续声称线性已满足。",
   "把结局改成连续": "结局类型由研究定义决定，不能为了模型任意改变。"
  }
 },
