 "t26_0": {
  "q": "因子分析（Factor Analysis）主要用于？",
  "choices": {
   "比较两组均数": "比较均数通常用相应检验或回归，不是潜结构提取。",
   "探索观测变量背后的潜在因子结构（如量表维度）": "因子分析寻找变量间的潜在共同因子，常用于量表的维度划分和结构效度检验。",
   "预测生存时间": "因子分析不直接处理事件时间与删失。",
   "检验正态性": "正态性是可能需检查的假设，不是因子分析主要用途。"
  }
 },
 "t26_1": {
  "q": "因子分析中的'变量共同度'（communality）指？",
  "choices": {
   "样本量": "共同度描述变量方差来源，不是观察人数。",
   "变量方差中被共同因子解释的比例": "共同度反映该变量的变异有多少能被提取的因子解释，共同度越大说明该变量与因子的关系越密切。",
   "变量均值": "均值是位置指标，不是共同因子解释比例。",
   "P值": "共同度是方差比例，不是检验P值。"
  }
 },
 "t26_2": {
  "q": "在进行因子分析时，对因子进行'旋转'（如varimax）的目的是？",
  "choices": {
   "减少样本量": "旋转改变载荷表达，不减少受试者数量。",
   "使因子载荷结构更清晰、便于解释": "旋转（正交旋转varimax/斜交旋转promax）让载荷矩阵两极分化，每个变量主要载荷在一个因子上，便于命名解释因子。",
   "提高P值": "旋转目的不是操纵显著性。",
   "消除数据缺失": "缺失需专门策略，旋转不填补缺失。"
  }
 },
 "t26_3": {
  "q": "开发一份新量表时，检验其结构效度应使用？",
  "choices": {
   "t检验": "t检验不能识别条目背后的多维潜结构。",
   "探索性因子分析（EFA）": "EFA通过因子分析考察题目是否按预设维度聚合，是量表结构效度检验的标准方法。",
   "卡方检验": "普通分类卡方不等同于因子模型结构效度分析。",
   "Logistic回归": "Logistic预测二分类结局，不提取量表潜因子。"
  }
 },
 "bank202609-t26-concept-1-1": {
  "q": "探索性因子分析主要寻找什么？",
  "choices": {
   "观测变量背后的潜在共同结构": "共同因子模型解释变量间共有协方差。",
   "随机分组结果": "因子结构与治疗随机分组结果不同。",
   "每个患者的治疗效应": "因子分析不识别每人的反事实治疗效应。",
   "事件发生时间": "事件时间是生存结局，不是一般因子提取目标。"
  }
 },
 "bank202609-t26-concept-2-1": {
  "q": "验证性因子分析通常应基于什么？",
  "choices": {
   "事先明确的结构假设": "CFA用于检验预定测量结构，不能把同样数据的探索当独立验证。",
   "只选最显著路径": "按显著性挑路径会使验证变成数据驱动探索。",
   "完全不设模型": "CFA需要指定因子与条目等结构。",
   "只看总均数": "总均数无法反映条目协方差与潜结构。"
  }
 },
 "bank202609-t26-concept-3-1": {
  "q": "斜交旋转允许什么？",
  "choices": {
   "因子间相关": "正交旋转限制因子正交，斜交旋转允许相关。",
   "所有载荷为1": "斜交允许因子相关，不要求每个载荷为1。",
   "样本无限大": "旋转方式不改变样本规模。",
   "残差必为0": "允许因子相关不代表所有特异误差消失。"
  }
 },
 "bank202609-t26-concept-4-1": {
  "q": "KMO较好能否证明量表全部有效？",
  "choices": {
   "不能": "KMO只是因子分析适用性的辅助信息。",
   "能": "KMO只涉及因子分析适宜性的一部分，不覆盖信效度全部证据。",
   "能证明因果": "相关结构适宜不等于因果关系成立。",
   "能替代外部效度": "推广到外部人群仍需独立的外部效度证据。"
  }
 },
