 "t27_0": {
  "q": "结局为'治愈/好转/无效'（有序等级），分析危险因素应选择？",
  "choices": {
   "二分类Logistic": "直接二分会丢失等级信息并改变问题。",
   "有序Logistic回归": "有序等级结局用有序（Ordinal）Logistic回归，估计累积优势比，需检验平行线假设。",
   "无序多分类Logistic": "多项模型可用但未利用有序结构，题设优先考虑有序模型及其假设。",
   "线性回归": "等级间距未必相等，不能直接当连续结局。"
  }
 },
 "t27_1": {
  "q": "结局为'血型A/B/AB/O'（无序多类）时，应选择？",
  "choices": {
   "二分类Logistic": "四类不能直接用普通二分类模型一次覆盖。",
   "无序多分类Logistic回归": "血型类别无内在顺序，用无序多分类Logistic回归，以一个类别为参照估计其他各类的相对OR。",
   "有序Logistic": "血型没有程度排序，不符合有序结局含义。",
   "t检验": "t检验针对连续均数，不分析四分类结局。"
  }
 },
 "t27_2": {
  "q": "条件Logistic回归适用于？",
  "choices": {
   "独立随机样本": "无匹配独立样本通常用普通Logistic，不需要匹配条件似然。",
   "1:n配对设计的病例对照研究": "条件Logistic用于配对（匹配）设计的病例对照研究，通过分层（每对为单位）控制匹配因素。",
   "横断面研究": "横断面本身不提供条件Logistic针对的匹配结构。",
   "任何数据": "方法需匹配数据结构，不能适用于任何数据。"
  }
 },
 "t27_3": {
  "q": "进行有序Logistic回归前需验证的重要假设是？",
  "choices": {
   "正态性": "有序结局不要求服从正态分布。",
   "平行线（比例优势）假设：各阈值处OR一致": "平行线假设要求自变量的效应在各累积阈值处一致，违背时结果不可靠，可改为无序多分类或广义有序模型。",
   "方差齐性": "连续残差方差齐性不是比例优势模型的核心特殊假设。",
   "独立性": "独立观察仍应考虑，但本题问有序Logistic特有的比例优势条件。"
  }
 },
 "bank202609-t27-concept-1-1": {
  "q": "结局为无序三分类，常用什么？",
  "choices": {
   "多项Logistic回归": "无序多分类模型与有序模型的假设不同。",
   "直接普通二项Logistic不改编码": "二项模型只接受两类结局，直接输入三类不匹配。",
   "配对t检验": "配对t比较连续差值，不是无序三分类概率。",
   "Cox只用类别": "没有时间和删失信息的类别不能直接作为Cox结局。"
  }
 },
 "bank202609-t27-concept-2-1": {
  "q": "有序Logistic常需检查哪项假设？",
  "choices": {
   "比例优势假设": "比例优势模型通常要求各累计切点有共同斜率。",
   "比例风险假设": "比例风险属于Cox类生存模型，不是比例优势。",
   "球形性": "球形性常见于重复测量ANOVA，不是有序Logistic。",
   "所有变量正态": "有序Logistic不要求所有变量正态。"
  }
 },
 "bank202609-t27-concept-3-1": {
  "q": "匹配病例对照数据可考虑什么？",
  "choices": {
   "条件Logistic回归": "条件分析可利用匹配集合的信息控制相应匹配因素。",
   "忽略匹配直接比较均数": "忽略匹配可能丢失设计信息，比较均数也不回答二分类结局。",
   "把匹配号当连续结局": "匹配号是分层标识，不是连续结局。",
   "KM曲线": "病例对照匹配并不提供KM所需的生存时间结构。"
  }
 },
 "bank202609-t27-concept-4-1": {
  "q": "多项Logistic的参考类别改变会怎样？",
  "choices": {
   "系数比较的基准改变": "参考类别决定对数优势对比的表达。",
   "患者结局改变": "换参考组只改变参数表达，不改变患者真实类别。",
   "总体样本量改变": "相同数据换参考组不增减样本。",
   "模型必不能拟合": "合理重编码通常可拟合，只是比较基准变化。"
  }
 },
 "t28_0": {
  "q": "研究某药物对'每月癫痫发作次数'的影响，结局为计数资料，应选择？",
  "choices": {
   "线性回归": "计数非负且离散，普通正态线性模型未必适合。",
   "泊松回归": "发作次数是计数值（0,1,2...），用泊松回归处理，其对数线性模型估计率比RR。",
   "二分类Logistic": "把次数二分会丢失发作频率信息。",
   "卡方检验": "简单卡方不能直接建模计数强度与协变量关系。"
  }
 },
 "t28_1": {
  "q": "泊松分布的特点之一是？",
  "choices": {
   "均数不等于方差": "理想泊松分布的定义是均值等于方差。",
   "均数=方差（λ）": "泊松分布的均数与方差相等（都等于参数λ），这一性质是选择泊松回归的依据。",
   "只适用于正态数据": "泊松是离散计数分布，与正态分布不同。",
   "必须是负值": "泊松计数取0及正整数，不能为负。"
  }
 },
 "t28_2": {
  "q": "当计数数据出现'过度离散'（方差明显大于均数）时，应改用？",
  "choices": {
   "线性回归": "普通线性模型不直接保持计数支持与均值方差关系。",
   "负二项回归": "过度离散时泊松回归标准误被低估，负二项回归引入额外离散参数，更适合方差>均数的计数数据。",
   "Logistic回归": "二项Logistic针对是否发生，不描述计数过度离散。",
   "Probit回归": "二项Probit同样针对二分类概率，不解决计数过度离散。"
  }
 },
 "t28_3": {
  "q": "Probit回归与Logistic回归的关系是？",
  "choices": {
   "完全相同": "两者链接函数和系数尺度不同，并非完全相同。",
   "都是二分类结局的连接函数模型，Probit用正态累积分布Φ，Logistic用S型logit": "两者都用S型函数连接二分类结局与线性预测，Probit用标准正态累积分布，Logistic用logit变换，结论通常接近。",
   "Probit用于连续结局": "标准二项Probit用于二分类概率，不是普通连续结局。",
   "Logistic用于计数": "普通二项Logistic针对二分类，计数通常需泊松或负二项等。"
  }
 },
 "bank202609-t28-concept-1-1": {
  "q": "Poisson计数回归中观察时长不同，常加入？",
  "choices": {
   "对数暴露时长作为offset": "offset使模型针对事件率而非简单计数比较。",
   "把时间当事件数": "观察时长与事件次数是不同变量，不能互换。",
   "直接删去长随访者": "删长随访者改变样本并浪费暴露信息。",
   "把所有计数变为1": "全部改成1会丢失次数差异，改变研究问题。"
  }
 },
 "bank202609-t28-concept-2-1": {
  "q": "计数方差明显超过均数，应考虑？",
  "choices": {
   "过度离散及替代模型": "负二项或适当稳健方法可用于部分过度离散情形。",
   "必为正态": "过度离散并不保证正态分布，仍可能高度偏态且离散。",
   "必为录入错误": "异质性或聚类可导致过度离散，不必是录入错。",
   "Poisson方差假设已充分满足": "方差明显大于均值正提示简单泊松方差关系可能不合适。"
  }
 },
 "bank202609-t28-concept-3-1": {
  "q": "Probit链接使用什么分布的分位函数？",
  "choices": {
   "标准正态": "Probit将概率通过标准正态逆分布函数映射到线性预测子。",
   "泊松": "泊松分布常描述计数，不是Probit的链接分布。",
   "均匀": "均匀分布分位函数不是标准Probit链接。",
   "指数": "指数分布通常用于等待时间，不是Probit链接。"
  }
 },
 "bank202609-t28-concept-4-1": {
  "q": "零计数特别多就一定该用零膨胀模型吗？",
  "choices": {
   "不一定，需结合生成机制和拟合": "零多可能由不同机制产生，模型选择需要依据。",
   "一定": "普通低均值计数模型也可产生大量零，需比较机制和拟合。",
   "只要一个零就必须": "一个零完全可能是正常计数，不能据此采用零膨胀模型。",
   "零必须全部删除": "零是有效观测，删除会造成截断和选择偏倚。"
  }
 },
